/// A single column in the watch TUI. The set of valid columns is fixed by
/// this enum — the `[watch]` config picks which ones to show and in what
/// order, but cannot introduce new ones.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum WatchColumn {
    Pane,
    Kind,
    State,
    StateAge,
    Model,
    Ctx,
    Cost,
    Limits,
    Workload,
    Prompt,
    Activity,
    Duration,
}

impl WatchColumn {
    /// Parse a config-string column key. Returns `None` for unknown keys
    /// so the caller can warn and skip rather than refuse to load.
    fn from_key(s: &str) -> Option<Self> {
        Some(match s {
            "pane" => Self::Pane,
            "kind" => Self::Kind,
            "state" => Self::State,
            "state_age" => Self::StateAge,
            "model" => Self::Model,
            "ctx" => Self::Ctx,
            "cost" => Self::Cost,
            "limits" => Self::Limits,
            "workload" => Self::Workload,
            "prompt" => Self::Prompt,
            "activity" => Self::Activity,
            "duration" => Self::Duration,
            _ => return None,
        })
    }

    fn header(self) -> &'static str {
        match self {
            Self::Pane => "NAME",
            Self::Kind => "KIND",
            Self::State => "ST",
            Self::StateAge => "STATE",
            Self::Model => "MODEL",
            Self::Ctx => "CTX%",
            Self::Cost => "COST$",
            Self::Limits => "LIMITS",
            Self::Workload => "TREE",
            Self::Prompt => "LAST PROMPT",
            Self::Activity => "ACT",
            Self::Duration => "DUR",
        }
    }

    fn default_width(self) -> Constraint {
        match self {
            // PANE — "session:window.pane" can run long; 22 covers most.
            Self::Pane => Constraint::Length(22),
            Self::Kind | Self::StateAge => Constraint::Length(12),
            // STATE — compact colored state marker; full state remains
            // available in detail placeholders and structured snapshots.
            Self::State => Constraint::Length(3),
            Self::Model => Constraint::Length(16),
            Self::Ctx => Constraint::Length(5),
            Self::Activity | Self::Duration => Constraint::Length(6),
            Self::Cost => Constraint::Length(7),
            // LIMITS — widest realistic payload is `⛔ 7d in 23h 59m`
            // (~17 cells with a wide-cell emoji). Wider columns crowd the
            // prompt; narrower ones clip the duration suffix on
            // emoji-greedy fonts.
            Self::Limits => Constraint::Length(18),
            Self::Workload => Constraint::Length(8),
            Self::Prompt => Constraint::Min(20),
        }
    }

    /// Build the `Text` content for one cell. Returning `Text` (rather
    /// than a finished `Cell`) lets the caller stack a second line on top
    /// of it when the row is selected and a detail template is enabled.
    fn agent_text<'a>(
        self,
        a: &'a Agent,
        now: OffsetDateTime,
        panes: &'a [PaneInfo],
        theme: WatchThemeSpec,
        spin: Spinner,
        summary: WatchSummary,
    ) -> Text<'a> {
        match self {
            Self::Pane => {
                let label = agent_pane_display(a, panes);
                // Dim the pane cell when there's nothing to attach to —
                // a deliberate visual signal that Enter won't do anything
                // useful for this row. Keeping the rest of the row's
                // columns at full brightness preserves readability of
                // state/prompt/etc.
                if a.pane.is_none() {
                    Text::from(Span::styled(
                        label,
                        Style::default()
                            .fg(Color::DarkGray)
                            .add_modifier(Modifier::DIM | Modifier::ITALIC),
                    ))
                } else {
                    label.into()
                }
            }
            Self::Kind => a.kind.to_string().into(),
            Self::State => {
                let (symbol, style) = state_marker(a.state, theme, spin);
                Text::from(Span::styled(symbol, style))
            }
            Self::StateAge => state_age_text(a, now, theme, spin),
            Self::Model => a.model.as_deref().unwrap_or("-").to_string().into(),
            Self::Ctx => a
                .context_used_pct
                .map_or_else(|| "-".into(), |p| format!("{p:>3.0}%"))
                .into(),
            Self::Cost => a
                .cost_usd
                .map_or_else(|| "-".into(), |c| format!("${c:.2}"))
                .into(),
            Self::Limits => limits_text(a, now),
            Self::Workload => workload_text(a),
            Self::Prompt => summary_line(a, summary).into(),
            Self::Activity => relative_time(a.last_activity_at, now).into(),
            Self::Duration => Text::from(Span::styled(
                "-",
                Style::default()
                    .fg(Color::DarkGray)
                    .add_modifier(Modifier::DIM),
            )),
        }
    }

    fn bare_text(self, p: &PaneInfo) -> Text<'_> {
        let dim = Style::default()
            .fg(Color::DarkGray)
            .add_modifier(Modifier::DIM);
        match self {
            Self::Pane => {
                let pane = format!("{}:{}.{}", p.session, p.window_index, p.pane_index);
                Text::from(Span::styled(pane, dim))
            }
            // Bare panes have no agent metadata. We surface the pane title /
            // current command in the prompt slot so the row still carries
            // useful at-a-glance info; everything else collapses to a dash.
            Self::Prompt => {
                let summary = if p.title.is_empty() || p.title == p.current_command {
                    p.current_command.clone()
                } else {
                    format!("{}  {}", p.current_command, p.title)
                };
                let summary: String = summary.chars().take(80).collect();
                Text::from(Span::styled(summary, dim))
            }
            Self::Kind | Self::State | Self::StateAge => Text::from(Span::styled("—", dim)),
            Self::Model
            | Self::Ctx
            | Self::Cost
            | Self::Limits
            | Self::Workload
            | Self::Activity
            | Self::Duration => Text::from(Span::styled("-", dim)),
        }
    }

    fn work_text<'a>(
        self,
        s: &'a WorkRow,
        now: OffsetDateTime,
        panes: &'a [PaneInfo],
        theme: WatchThemeSpec,
        spin: Spinner,
        summary: WatchSummary,
    ) -> Text<'a> {
        let dim = theme.dim_style().add_modifier(Modifier::DIM);
        if matches!(self, Self::StateAge) {
            return session_state_age_text(s, now, theme, spin);
        }
        let Some(agent) = s.latest_agent.as_ref() else {
            return match self {
                Self::Pane => work_label(s, theme, spin),
                Self::Prompt => Text::from(Span::styled(
                    s.bare_summary.clone().unwrap_or_else(|| {
                        format!("{} pane{}", s.pane_count, plural(s.pane_count))
                    }),
                    dim,
                )),
                Self::Duration => duration_text(s, now),
                Self::Kind | Self::State | Self::StateAge => Text::from(Span::styled("—", dim)),
                Self::Model | Self::Ctx | Self::Cost | Self::Limits | Self::Activity => {
                    Text::from(Span::styled("-", dim))
                }
                Self::Workload => Text::from(Span::styled("-", dim)),
            };
        };

        match self {
            Self::Pane => work_label(s, theme, spin),
            Self::Kind
            | Self::State
            | Self::StateAge
            | Self::Model
            | Self::Ctx
            | Self::Cost
            | Self::Limits
            | Self::Prompt
            | Self::Activity => self.agent_text(agent, now, panes, theme, spin, summary),
            Self::Workload => work_workload_text(s),
            Self::Duration => duration_text(s, now),
        }
    }
}

/// Resolve the configured column list against `WatchConfig`. Unknown keys
/// are skipped with a `tracing::warn!` rather than aborting.
pub(crate) fn resolve_columns(cfg: &WatchConfig) -> Vec<WatchColumn> {
    let mut out = Vec::with_capacity(cfg.columns.len());
    for key in &cfg.columns {
        if let Some(c) = WatchColumn::from_key(key) {
            out.push(c);
        } else {
            tracing::warn!(column = %key, "unknown watch column key, skipping");
        }
    }
    // Warn (once each) on widths entries with no matching column. This
    // catches typos like `widths.prompts = 30` that would otherwise be
    // silently ignored.
    for key in cfg.widths.keys() {
        if WatchColumn::from_key(key).is_none() {
            tracing::warn!(column = %key, "unknown watch.widths key, ignoring");
        }
    }
    out
}

/// Resolve columns and apply the window-view duration default. This is used
/// both at startup and when `:view` changes granularity at runtime so the two
/// paths cannot drift into different table shapes.
fn resolve_display_columns(cfg: &WatchConfig) -> Vec<WatchColumn> {
    let mut columns = resolve_columns(cfg);
    if cfg.view == WatchView::Window && !columns.contains(&WatchColumn::Duration) {
        // The default layout carries STATE (glyph + state + age). In window
        // view the leftmost cluster of the WORK cell already shows every
        // state as icon-with-count, so a STATE column is the same fact
        // twice — and 12 columns wide. Swap it for DUR rather than keeping
        // both; DUR + ACT is the whole timing story.
        if columns.as_slice()
            == [
                WatchColumn::Pane,
                WatchColumn::StateAge,
                WatchColumn::Activity,
                WatchColumn::Prompt,
            ]
            || columns.as_slice()
                == [
                    WatchColumn::Pane,
                    WatchColumn::State,
                    WatchColumn::Activity,
                    WatchColumn::Prompt,
                ]
        {
            columns = vec![
                WatchColumn::Pane,
                WatchColumn::Duration,
                WatchColumn::Activity,
                WatchColumn::Prompt,
            ];
        } else {
            let insert_at = columns
                .iter()
                .position(|c| matches!(c, WatchColumn::Prompt | WatchColumn::Activity))
                .unwrap_or(columns.len());
            columns.insert(insert_at, WatchColumn::Duration);
        }
    }
    columns
}

/// Resolve the width Constraint for `col`, falling back to its default
/// when the config has no entry or an `Invalid` spec.
fn resolve_width(col: WatchColumn, cfg: &WatchConfig) -> Constraint {
    let key = col.config_key();
    match cfg.widths.get(key) {
        Some(WidthSpec::Length(n)) => Constraint::Length(*n),
        Some(WidthSpec::Min(n)) => Constraint::Min(*n),
        Some(WidthSpec::Percentage(n)) => Constraint::Percentage((*n).min(100)),
        Some(WidthSpec::Invalid(raw)) => {
            tracing::warn!(column = %key, value = %raw, "invalid watch.widths value, using default");
            col.default_width()
        }
        None => col.default_width(),
    }
}

impl WatchColumn {
    fn config_key(self) -> &'static str {
        match self {
            Self::Pane => "pane",
            Self::Kind => "kind",
            Self::State => "state",
            Self::StateAge => "state_age",
            Self::Model => "model",
            Self::Ctx => "ctx",
            Self::Cost => "cost",
            Self::Limits => "limits",
            Self::Workload => "workload",
            Self::Prompt => "prompt",
            Self::Activity => "activity",
            Self::Duration => "duration",
        }
    }
}

/// One row of the dashboard. Either a tracked muxa agent or a plain tmux
/// pane the daemon doesn't know about — listing both makes `muxa watch` a
/// drop-in replacement for tmux's `choose-tree -Zs`.
pub(crate) enum WatchRow {
    Agent(Box<Agent>),
    BarePane(Box<PaneInfo>),
    Work(Box<WorkRow>),
}

/// Stable identity of a table row, used to keep the cursor pinned to the
/// same work / agent / pane across refreshes and re-sorts.
///
/// Deliberately *not* based on `pane_id`: a work row's
/// `representative_pane` is whichever of its agents was most recently
/// active, so it changes on its own as the work progresses. Identity has to
/// survive that.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum RowIdentity {
    Topology(TopologyNodeKey),
    Agent(AgentKind, String),
    BarePane(PaneKey),
    Work(WorkIdentity),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct WorkIdentity {
    window_key: Option<WindowKey>,
    fallback: String,
}

/// One selectable line after runtime filtering and optional work
/// expansion have been applied. `agent_idx` points at a child agent inside a
/// work row; `None` is the ordinary top-level row.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct VisibleTarget {
    row_idx: usize,
    agent_idx: Option<usize>,
}

/// One selectable line in the canonical tree presentation. The stable key is
/// the selection identity; depth and branch flags are presentation-only and
/// are rebuilt from the current snapshot on every render/filter operation.
#[derive(Debug, Clone, PartialEq, Eq)]
#[allow(clippy::struct_excessive_bools)] // independent branch/disclosure rendering facts
struct TreeTarget {
    key: TopologyNodeKey,
    /// The only window folded into this session row in pane view. The row
    /// keeps its session identity/action semantics, while rendering the work
    /// name and exposing the window's panes as direct visual children.
    compacted_window: Option<WindowKey>,
    depth: u8,
    is_last_sibling: bool,
    parent_is_last_sibling: bool,
    has_children: bool,
    expanded: bool,
}

/// One-shot context used to place the cursor after the initial empty frame.
/// The endpoint is present when the invoking multiplexer exposes it, allowing
/// `%N` values repeated on another socket to resolve without guessing.
#[derive(Debug, Clone, PartialEq, Eq)]
struct InitialPaneHint {
    pane_id: String,
    endpoint: Option<BackendEndpoint>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum WatchEventKind {
    Done,
    Attention,
    Error,
}

#[derive(Debug, Clone)]
struct WatchEventEntry {
    kind: WatchEventKind,
    state: AgentState,
    label: String,
    summary: String,
    occurred_at: OffsetDateTime,
}

const MAX_WATCH_EVENTS: usize = 50;

#[derive(Debug, Clone)]
pub(crate) struct WorkRow {
    /// Parent workspace id: tmux session name or herdr workspace id. Activity
    /// remains session/workspace-scoped even though each tmux row is one window.
    pub session: String,
    /// Host-namespaced work identity. tmux keys include stable session and
    /// window ids; other hosts keep their native workspace grouping.
    pub group_key: String,
    /// Canonical identity of this backend window/tab. `None` is reserved for
    /// paneless/stale fallback rows that have no observable topology node.
    pub window_key: Option<WindowKey>,
    /// Human-facing `workspace › work` label on tmux; native workspace label
    /// on hosts that do not expose a window-level work unit.
    pub display_name: String,
    pub pane_ids: Vec<String>,
    pub representative_pane: Option<String>,
    pub latest_agent: Option<Agent>,
    pub agents: Vec<Agent>,
    pub pane_count: usize,
    pub bare_summary: Option<String>,
    pub activity: Option<SessionActivity>,
    /// `(reported, total)` over this work's pipeline agents, or `None` when
    /// the window has none — a hand-split pane never reports, so a ratio
    /// there would read as unfinished work that was never a pipeline.
    ///
    /// Without this a converged pipeline and a stalled one are the same
    /// picture: every agent idle, nothing to say the review already landed.
    pub completion: Option<(usize, usize)>,
    pub pipeline_run: Option<muxa::pipeline_run::PipelineRunSummary>,
    agent_states: HashMap<(AgentKind, String), AgentState>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum WatchSortPreset {
    Name,
    Latest,
    Duration,
    State,
}

impl WatchSortPreset {
    fn keys(self) -> Vec<WatchSortKey> {
        match self {
            Self::Name => vec![WatchSortKey::Name, WatchSortKey::Activity],
            Self::Latest => vec![WatchSortKey::Activity],
            Self::Duration => vec![WatchSortKey::Duration],
            Self::State => vec![WatchSortKey::State, WatchSortKey::Activity],
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Name => "NAME",
            Self::Latest => "LATEST",
            Self::Duration => "DUR",
            Self::State => "ST",
        }
    }
}

fn sort_label(keys: &[WatchSortKey]) -> &'static str {
    match keys.first().copied() {
        Some(WatchSortKey::Name) | None => "NAME",
        Some(WatchSortKey::Activity) => "LATEST",
        Some(WatchSortKey::Duration) => "DUR",
        Some(WatchSortKey::State) => "ST",
        Some(WatchSortKey::Pane) => "PANE",
        Some(WatchSortKey::PaneId) => "PANE ID",
    }
}

fn sort_key_toml_name(key: WatchSortKey) -> &'static str {
    match key {
        WatchSortKey::Name => "name",
        WatchSortKey::Activity => "latest",
        WatchSortKey::Duration => "duration",
        WatchSortKey::State => "state",
        WatchSortKey::Pane => "pane",
        WatchSortKey::PaneId => "pane_id",
    }
}

fn persist_watch_sort(path: &Path, keys: &[WatchSortKey]) -> std::result::Result<(), String> {
    let original = match std::fs::read_to_string(path) {
        Ok(s) => s,
        Err(e) if e.kind() == io::ErrorKind::NotFound => String::new(),
        Err(e) => return Err(format!("read {}: {e}", path.display())),
    };

    let mut doc = if original.trim().is_empty() {
        toml_edit::DocumentMut::new()
    } else {
        original
            .parse::<toml_edit::DocumentMut>()
            .map_err(|e| format!("parse {}: {e}", path.display()))?
    };

    match doc.get("watch") {
        Some(toml_edit::Item::Table(_)) | None => {}
        Some(_) => return Err("[watch] is not a table".to_string()),
    }
    if doc.get("watch").is_none() {
        doc["watch"] = toml_edit::Item::Table(toml_edit::Table::new());
    }

    let watch = doc["watch"]
        .as_table_mut()
        .ok_or_else(|| "[watch] is not a table".to_string())?;
    let mut sort = toml_edit::Array::new();
    for key in keys {
        sort.push(sort_key_toml_name(*key));
    }
    watch["sort"] = toml_edit::Item::Value(toml_edit::Value::Array(sort));

    if let Some(parent) = path.parent().filter(|p| !p.as_os_str().is_empty()) {
        std::fs::create_dir_all(parent).map_err(|e| format!("create {}: {e}", parent.display()))?;
    }
    std::fs::write(path, doc.to_string()).map_err(|e| format!("write {}: {e}", path.display()))
}

impl WatchRow {
    fn agent(agent: Agent) -> Self {
        Self::Agent(Box::new(agent))
    }

    fn pane_id(&self) -> Option<&str> {
        match self {
            Self::Agent(a) => a.pane.as_deref(),
            Self::BarePane(p) => Some(&p.pane_id),
            Self::Work(s) => s.representative_pane.as_deref(),
        }
    }

    /// Identity that survives a rebuild of the row set — see [`RowIdentity`].
    fn identity(&self) -> RowIdentity {
        match self {
            Self::Agent(a) => RowIdentity::Agent(a.kind, a.session_id.clone()),
            Self::BarePane(p) => RowIdentity::BarePane(PaneKey::from_pane(
                muxa::backend::pane_id_host_kind(&p.pane_id).unwrap_or(muxa::HostKind::Tmux),
                p,
            )),
            Self::Work(s) => RowIdentity::Work(WorkIdentity {
                window_key: s.window_key.clone(),
                fallback: s.group_key.clone(),
            }),
        }
    }

    fn contains_pane(&self, pane_id: &str) -> bool {
        match self {
            Self::Agent(a) => a.pane.as_deref() == Some(pane_id),
            Self::BarePane(p) => p.pane_id == pane_id,
            Self::Work(s) => {
                s.representative_pane.as_deref() == Some(pane_id)
                    || s.pane_ids.iter().any(|id| id == pane_id)
                    || s.agents.iter().any(|a| a.pane.as_deref() == Some(pane_id))
            }
        }
    }
}

/// A daemon error to surface in the header. We track whether the inner
/// error is the "daemon not reachable" variant so the renderer can drop the
/// `daemon error: ` prefix — otherwise the message reads
/// "daemon error: daemon not reachable at …" which is awkward.
pub(crate) struct DaemonError {
    pub message: String,
    pub self_describing: bool,
}

/// A power-user action requested against the currently-selected row.
///
/// The input handler returns one of these (or `None`) and a separate
/// helper executes it via [`dispatch_quick_action`]. Keeping the
/// "what should happen" decision separate from "shell out to tmux /
/// xclip" lets unit tests verify the selection logic without touching
/// the real subprocess world — see the `Effects` trait below.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum QuickAction {
    /// Close the exact selected session/window/pane. The key carries the
    /// backend endpoint so repeated native ids cannot hit another server.
    TerminateNode(TopologyNodeKey),
    /// Interrupt the exact selected agent pane without closing it.
    InterruptPane(PaneKey),
    /// Kill the tmux pane the agent is running in. String is the
    /// `pane_id` (e.g. `%42`) we'll pass to `tmux kill-pane -t`.
    KillPane(String),
    /// Send Ctrl-C to the pane to abort the current turn. The spec
    /// originally called this "restart"; the pragmatic shape is just
    /// "abort" because we don't know the original launch command to
    /// re-run reliably across Claude/Codex/Gemini wrappers.
    AbortTurn(String),
    /// Copy the selected agent's `last_prompt` to the system clipboard.
    /// String is the prompt body; the dispatcher tries pbcopy / wl-copy
    /// / xclip in order and falls back to a temp file if none work.
    CopyPrompt(String),
    /// Send a freshly-authored prompt straight into the selected pane.
    /// The dispatcher writes the text literally, waits briefly, then
    /// sends Enter as a separate key so the target agent submits it.
    SendPrompt { pane_id: String, text: String },
    /// Endpoint-pinned form used by the topology tree. Raw `%N` is not a
    /// sufficient control target when multiple tmux sockets are visible.
    SendPromptTo { pane: PaneKey, text: String },
    /// Toggle the `?` help overlay. Pure UI — no side-effects.
    ShowHelp,
    /// Legacy no-selection fallback: create or reuse a session and window at `dir`, then
    /// start an agent pane with its first prompt on the command line. The launch
    /// string is fully assembled (and shell-quoted) by the spawn form so
    /// the dispatcher stays a dumb pipe.
    SpawnWork {
        dir: String,
        agent_label: &'static str,
        launch: String,
        /// Explicit Work id; `None` derives one from the directory.
        work: Option<String>,
    },
    /// Spawn relative to an exact selected topology node. Session targets
    /// create a new window; window/pane targets add a sibling pane.
    SpawnAt {
        target: TopologyNodeKey,
        dir: String,
        name: String,
        agent_label: &'static str,
        launch: String,
    },
}

/// Payload behind the shared y/N confirmation popup. Most confirmations are
/// synchronous quick actions; clearing ask history is daemon-owned and must be
/// dispatched asynchronously by the run loop instead.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum ConfirmAction {
    Quick(QuickAction),
    DeleteAskHistory(String),
    ClearAskHistory,
    DeleteMessageSkill(String),
}

/// Outcome of running a [`QuickAction`] — surfaced to the run loop
/// which then turns it into a transient footer hint or a state mutation.
///
/// Note that "not applicable" is handled at the **input-handler** stage
/// (via `Action::NotApplicable`) rather than here: by the time the
/// dispatcher runs we've already decided the action is going through,
/// so anything the dispatcher reports back is either success or a
/// real backend failure.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum ActionOutcome {
    /// Action ran successfully. Message goes into the footer hint.
    Ok(String),
    /// Action failed (tmux exited non-zero, clipboard binaries all
    /// missing, …). Message goes into the footer hint with an error tone.
    Err(String),
    /// Help overlay toggled — no hint to surface; the renderer reads
    /// `app.help_open` directly.
    HelpToggled,
}

/// Side-effect surface for [`dispatch_quick_action`]. Lifting the three
/// shell-outs into a trait means tests can pass a `RecorderEffects`
/// stub that records calls without ever spawning a subprocess.
pub(crate) trait Effects {
    /// Run `tmux kill-pane -t <pane_id>`. Return Ok on exit 0.
    fn kill_pane(&mut self, pane_id: &str) -> std::result::Result<(), String>;
    /// Run `tmux send-keys -t <pane_id> C-c`. Return Ok on exit 0.
    fn send_ctrl_c(&mut self, pane_id: &str) -> std::result::Result<(), String>;
    fn terminate_node(&mut self, key: &TopologyNodeKey) -> std::result::Result<(), String> {
        match key {
            TopologyNodeKey::Pane(pane) => self.kill_pane(&pane.pane_id),
            TopologyNodeKey::Session(_) | TopologyNodeKey::Window(_) => {
                Err("hierarchy close is not implemented by this effect sink".into())
            }
        }
    }
    fn interrupt_pane(&mut self, key: &PaneKey) -> std::result::Result<(), String> {
        self.send_ctrl_c(&key.pane_id)
    }
    /// Pipe `text` into the system clipboard. Returns the name of the
    /// helper that succeeded (`pbcopy` / `wl-copy` / `xclip`) or
    /// `tmpfile:<path>` if all helpers were missing and we wrote a
    /// fallback file. `Err()` when even the fallback failed.
    fn copy_to_clipboard(&mut self, text: &str) -> std::result::Result<String, String>;
    /// Send `text` to `pane_id` as literal terminal input, then press
    /// Enter after a short grace delay. Return Ok only if both tmux
    /// calls succeed.
    fn send_prompt(&mut self, pane_id: &str, text: &str) -> std::result::Result<(), String>;
    fn send_prompt_to(&mut self, pane: &PaneKey, text: &str) -> std::result::Result<(), String> {
        self.send_prompt(&pane.pane_id, text)
    }
    /// Create or reuse one managed session/window and start an agent pane.
    /// The explicit name is the window/ticket id; otherwise cwd derives it.
    fn spawn_work(
        &mut self,
        dir: &str,
        launch: &str,
        work: Option<&str>,
    ) -> std::result::Result<String, String>;
    fn spawn_at(
        &mut self,
        target: &TopologyNodeKey,
        dir: &str,
        name: &str,
        agent_label: &str,
        launch: &str,
    ) -> std::result::Result<String, String> {
        let _ = target;
        self.spawn_work(dir, launch, (!name.is_empty()).then_some(name))
            .map(|result| format!("{result} ({agent_label})"))
    }
}

/// Real-world `Effects` impl — shells out to tmux and the system
/// clipboard helpers. Unit tests use a recorder stub instead.
pub(crate) struct RealEffects;

struct SpawnWorkPlan {
    session: String,
    created_workspace: bool,
    created_work: bool,
    args: Vec<String>,
}

fn plan_spawn_work(
    cwd: &Path,
    workspace: &str,
    work: &str,
    launch: &str,
) -> std::result::Result<SpawnWorkPlan, String> {
    let existing_workspace =
        crate::tmux_work::find_workspace(workspace).map_err(|error| error.to_string())?;
    if let Some(existing) =
        crate::tmux_work::find_work_in(work, Some(workspace)).map_err(|error| error.to_string())?
    {
        let existing_cwd = std::fs::canonicalize(&existing.cwd)
            .map_err(|error| format!("resolve {}: {error}", existing.cwd.display()))?;
        if existing_cwd != cwd {
            return Err(format!(
                "work {} already uses {}; requested {}",
                existing.work,
                existing_cwd.display(),
                cwd.display()
            ));
        }
        return Ok(SpawnWorkPlan {
            session: existing.session,
            created_workspace: false,
            created_work: false,
            args: vec![
                "split-window".to_string(),
                "-h".into(),
                "-d".into(),
                "-P".into(),
                "-F".into(),
                "#{pane_id}".into(),
                "-t".into(),
                existing.window,
                "-c".into(),
                cwd.display().to_string(),
                launch.to_string(),
            ],
        });
    }

    let window_name =
        crate::tmux_work::window_name_for_work(work).map_err(|error| error.to_string())?;
    if let Some(existing) = existing_workspace {
        return Ok(SpawnWorkPlan {
            session: existing.session.clone(),
            created_workspace: false,
            created_work: true,
            args: vec![
                "new-window".to_string(),
                "-d".into(),
                "-P".into(),
                "-F".into(),
                "#{pane_id}".into(),
                "-t".into(),
                existing.session,
                "-n".into(),
                window_name,
                "-c".into(),
                cwd.display().to_string(),
                launch.to_string(),
            ],
        });
    }

    let session = crate::tmux_work::session_name_for_workspace(workspace)
        .map_err(|error| error.to_string())?;
    Ok(SpawnWorkPlan {
        session: session.clone(),
        created_workspace: true,
        created_work: true,
        args: vec![
            "new-session".to_string(),
            "-d".into(),
            "-P".into(),
            "-F".into(),
            "#{pane_id}".into(),
            "-s".into(),
            session,
            "-n".into(),
            window_name,
            "-c".into(),
            cwd.display().to_string(),
            launch.to_string(),
        ],
    })
}

impl Effects for RealEffects {
    fn spawn_at(
        &mut self,
        target: &TopologyNodeKey,
        dir: &str,
        name: &str,
        agent_label: &str,
        launch: &str,
    ) -> std::result::Result<String, String> {
        let endpoint = match target {
            TopologyNodeKey::Session(session) => &session.endpoint,
            TopologyNodeKey::Window(window) => &window.session.endpoint,
            TopologyNodeKey::Pane(pane) => &pane.window.session.endpoint,
        };
        if endpoint.host != muxa::HostKind::Tmux {
            return Err(format!("{} topology spawn is not supported", endpoint.host));
        }
        let cwd = std::fs::canonicalize(dir).map_err(|error| format!("resolve {dir}: {error}"))?;
        let cwd = cwd.display().to_string();
        let args = match target {
            TopologyNodeKey::Session(session) => {
                if name.trim().is_empty() {
                    return Err("a new window needs a name".into());
                }
                vec![
                    "new-window".to_string(),
                    "-d".into(),
                    "-P".into(),
                    "-F".into(),
                    "#{pane_id}".into(),
                    "-t".into(),
                    session.session_id.clone(),
                    "-n".into(),
                    name.to_string(),
                    "-c".into(),
                    cwd,
                    launch.to_string(),
                ]
            }
            TopologyNodeKey::Window(window) => vec![
                "split-window".to_string(),
                "-h".into(),
                "-d".into(),
                "-P".into(),
                "-F".into(),
                "#{pane_id}".into(),
                "-t".into(),
                window.window_id.clone(),
                "-c".into(),
                cwd,
                launch.to_string(),
            ],
            TopologyNodeKey::Pane(pane) => vec![
                "split-window".to_string(),
                "-h".into(),
                "-d".into(),
                "-P".into(),
                "-F".into(),
                "#{pane_id}".into(),
                "-t".into(),
                pane.window.window_id.clone(),
                "-c".into(),
                cwd,
                launch.to_string(),
            ],
        };
        let output = muxa::tmux::tmux_command_on(Some(&endpoint.socket))
            .args(&args)
            .output()
            .map_err(|error| format!("tmux: {error}"))?;
        if !output.status.success() {
            return Err(String::from_utf8_lossy(&output.stderr).trim().to_string());
        }
        let pane = String::from_utf8_lossy(&output.stdout)
            .lines()
            .map(str::trim)
            .find(|line| line.starts_with('%'))
            .ok_or_else(|| "tmux returned no pane id".to_string())?
            .to_string();
        muxa::tmux::run_control_on(
            Some(&endpoint.socket),
            &["set-option", "-p", "-t", &pane, "@muxa_agent", agent_label],
        )
        .and_then(|()| {
            muxa::tmux::run_control_on(
                Some(&endpoint.socket),
                &["set-option", "-p", "-t", &pane, "@muxa_managed_agent", "1"],
            )
        })
        .map_err(|error| format!("record pane metadata: {error}"))?;
        Ok(format!("{} pane {pane}", topology_key_label(target)))
    }

    fn terminate_node(&mut self, key: &TopologyNodeKey) -> std::result::Result<(), String> {
        let (endpoint, command, target) = match key {
            TopologyNodeKey::Session(session) => (
                &session.endpoint,
                "kill-session",
                session.session_id.as_str(),
            ),
            TopologyNodeKey::Window(window) => (
                &window.session.endpoint,
                "kill-window",
                window.window_id.as_str(),
            ),
            TopologyNodeKey::Pane(pane) => (
                &pane.window.session.endpoint,
                "kill-pane",
                pane.pane_id.as_str(),
            ),
        };
        if endpoint.host != muxa::HostKind::Tmux {
            return Err(format!(
                "{} hierarchy close is not supported",
                endpoint.host
            ));
        }
        muxa::tmux::run_control_on(Some(&endpoint.socket), &[command, "-t", target])
            .map_err(|error| error.to_string())
    }

    fn interrupt_pane(&mut self, key: &PaneKey) -> std::result::Result<(), String> {
        let endpoint = &key.window.session.endpoint;
        if endpoint.host != muxa::HostKind::Tmux {
            return Err(format!("{} pane interrupt is not supported", endpoint.host));
        }
        muxa::tmux::run_control_on(
            Some(&endpoint.socket),
            &["send-keys", "-t", &key.pane_id, "C-c"],
        )
        .map_err(|error| error.to_string())
    }

    fn kill_pane(&mut self, pane_id: &str) -> std::result::Result<(), String> {
        run_status("tmux", &["kill-pane", "-t", pane_id])
    }

    fn send_ctrl_c(&mut self, pane_id: &str) -> std::result::Result<(), String> {
        run_status("tmux", &["send-keys", "-t", pane_id, "C-c"])
    }

    fn send_prompt(&mut self, pane_id: &str, text: &str) -> std::result::Result<(), String> {
        send_prompt_to_tmux(
            pane_id,
            text,
            PROMPT_SUBMIT_GRACE,
            |args| run_status("tmux", args),
            std::thread::sleep,
        )
    }

    fn send_prompt_to(&mut self, pane: &PaneKey, text: &str) -> std::result::Result<(), String> {
        let endpoint = &pane.window.session.endpoint;
        if endpoint.host != muxa::HostKind::Tmux {
            return Err(format!("{} pane prompt is not supported", endpoint.host));
        }
        send_prompt_to_tmux(
            &pane.pane_id,
            text,
            PROMPT_SUBMIT_GRACE,
            |args| {
                muxa::tmux::run_control_on(Some(&endpoint.socket), args)
                    .map_err(|error| error.to_string())
            },
            std::thread::sleep,
        )
    }

    fn spawn_work(
        &mut self,
        dir: &str,
        launch: &str,
        explicit_work: Option<&str>,
    ) -> std::result::Result<String, String> {
        let base = explicit_work.map_or_else(|| session_base_name(dir), str::to_string);
        let work = crate::tmux_work::normalize_work_id(&base).map_err(|error| error.to_string())?;
        let cwd = std::fs::canonicalize(dir).map_err(|error| format!("resolve {dir}: {error}"))?;
        let workspace =
            crate::tmux_work::workspace_id_for_cwd(&cwd).map_err(|error| error.to_string())?;
        let plan = plan_spawn_work(&cwd, &workspace, &work, launch)?;
        let output = muxa::tmux::tmux_command_scoped()
            .args(&plan.args)
            .output()
            .map_err(|error| format!("tmux: {error}"))?;
        if !output.status.success() {
            return Err(String::from_utf8_lossy(&output.stderr).trim().to_string());
        }
        let pane = String::from_utf8_lossy(&output.stdout)
            .lines()
            .map(str::trim)
            .find(|line| line.starts_with('%'))
            .ok_or_else(|| "tmux returned no pane id".to_string())?
            .to_string();
        let agent = launch.split_whitespace().next().unwrap_or("unknown");
        let window =
            crate::tmux_work::window_id_for_pane(&pane).map_err(|error| error.to_string())?;
        let marked = (|| {
            if plan.created_workspace {
                crate::tmux_work::mark_workspace(&plan.session, &workspace, &cwd)?;
            }
            if plan.created_work {
                crate::tmux_work::mark_work(&window, &workspace, &work, &cwd)?;
            }
            crate::tmux_work::mark_agent(
                &pane,
                agent,
                Some(&workspace),
                Some(&work),
                None,
                None,
                // No alias here, so the socket is never read — but passing
                // the real one keeps the contract honest if that changes.
                None,
                None,
                &muxa::paths::default_socket(),
            )
        })();
        if let Err(error) = marked {
            crate::tmux_work::cleanup_pane(&pane);
            return Err(format!("record muxa tmux metadata: {error}"));
        }
        Ok(format!("{workspace}/{work}"))
    }

    fn copy_to_clipboard(&mut self, text: &str) -> std::result::Result<String, String> {
        // Backend priority — first one that's *applicable* and
        // succeeds wins. We cascade past Failed (not just
        // NotFound) so an installed-but-broken backend (e.g.
        // `xclip` present without an X server) doesn't strand the
        // user; the /tmp fallback at the bottom is the safety
        // net.
        //
        //   1. tmux load-buffer when $TMUX is set — works in pure
        //      SSH/headless because tmux owns its own paste buffer
        //      (`prefix + ]`) and on tmux 3.2+ with
        //      `set -g set-clipboard on` it transparently forwards
        //      to the host terminal's clipboard via OSC 52. Single
        //      backend that covers most of the "remote dev" case.
        //   2. pbcopy on macOS (unconditional — pbcopy is always
        //      present on Apple shells).
        //   3. wl-copy when $WAYLAND_DISPLAY is set.
        //   4. xclip / xsel when $DISPLAY is set. Pre-flight env
        //      check skips them entirely on headless hosts so we
        //      don't even produce the misleading "exit 1" the user
        //      hit before this fix.
        //   5. /tmp/muxa-clip-<ts>.txt as the last resort.
        struct Cand<'a> {
            label: &'a str,
            bin: &'a str,
            args: &'a [&'a str],
            applicable: bool,
        }

        let in_tmux = std::env::var_os("TMUX").is_some();
        let in_wayland = std::env::var_os("WAYLAND_DISPLAY").is_some();
        let in_x11 = std::env::var_os("DISPLAY").is_some();
        let candidates: &[Cand] = &[
            Cand {
                label: "tmux",
                bin: "tmux",
                args: &["load-buffer", "-"],
                applicable: in_tmux,
            },
            Cand {
                label: "pbcopy",
                bin: "pbcopy",
                args: &[],
                applicable: cfg!(target_os = "macos"),
            },
            Cand {
                label: "wl-copy",
                bin: "wl-copy",
                args: &[],
                applicable: in_wayland,
            },
            Cand {
                label: "xclip",
                bin: "xclip",
                args: &["-selection", "clipboard"],
                applicable: in_x11,
            },
            Cand {
                label: "xsel",
                bin: "xsel",
                args: &["--clipboard", "--input"],
                applicable: in_x11,
            },
        ];
        for c in candidates {
            if !c.applicable {
                continue;
            }
            // Cascade past Failed AND NotFound — the user never saw
            // a successful copy, so trying the next backend is
            // strictly more useful than surfacing one backend's
            // error.
            if pipe_to_command(c.bin, c.args, text).is_ok() {
                return Ok(c.label.to_string());
            }
        }
        // Last-resort fallback: dump to /tmp so the user can `cat` it.
        let path = format!(
            "/tmp/muxa-clip-{}.txt",
            OffsetDateTime::now_utc().unix_timestamp()
        );
        std::fs::write(&path, text).map_err(|e| format!("write {path}: {e}"))?;
        Ok(format!("tmpfile:{path}"))
    }
}

fn send_prompt_to_tmux<R, S>(
    pane_id: &str,
    text: &str,
    submit_delay: Duration,
    mut run_tmux: R,
    mut sleep: S,
) -> std::result::Result<(), String>
where
    R: FnMut(&[&str]) -> std::result::Result<(), String>,
    S: FnMut(Duration),
{
    run_tmux(&["send-keys", "-t", pane_id, "-l", "--", text])?;
    if !submit_delay.is_zero() {
        sleep(submit_delay);
    }
    run_tmux(&["send-keys", "-t", pane_id, "Enter"])
}

/// Result of attempting to spawn-and-pipe to a clipboard helper.
enum PipeErr {
    /// The binary itself wasn't on PATH — caller should try the next.
    NotFound,
    /// The binary ran but returned non-zero, or stdin write failed.
    /// The String describes the failure for ad-hoc logging; current
    /// callers cascade past `Failed` to the next backend so the
    /// payload isn't surfaced anywhere user-visible — but it stays
    /// for debug traces and future use.
    #[allow(dead_code)]
    Failed(String),
}

fn pipe_to_command(bin: &str, args: &[&str], text: &str) -> std::result::Result<(), PipeErr> {
    let mut cmd = Command::new(bin);
    cmd.args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::null())
        .stderr(Stdio::null());
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) if e.kind() == io::ErrorKind::NotFound => return Err(PipeErr::NotFound),
        Err(e) => return Err(PipeErr::Failed(format!("{bin}: {e}"))),
    };
    if let Some(mut stdin) = child.stdin.take() {
        if let Err(e) = stdin.write_all(text.as_bytes()) {
            return Err(PipeErr::Failed(format!("{bin} stdin: {e}")));
        }
    }
    match child.wait() {
        Ok(s) if s.success() => Ok(()),
        Ok(s) => Err(PipeErr::Failed(format!(
            "{bin} exited with {}",
            s.code().map_or_else(|| "signal".into(), |c| c.to_string())
        ))),
        Err(e) => Err(PipeErr::Failed(format!("{bin}: {e}"))),
    }
}

fn run_status(bin: &str, args: &[&str]) -> std::result::Result<(), String> {
    match Command::new(bin).args(args).status() {
        Ok(s) if s.success() => Ok(()),
        Ok(s) => Err(format!(
            "{bin} {} exited with {}",
            args.join(" "),
            s.code().map_or_else(|| "signal".into(), |c| c.to_string())
        )),
        Err(e) => Err(format!("{bin}: {e}")),
    }
}

/// Run a [`QuickAction`] against an [`Effects`] sink and return what
/// the run loop should surface in the footer. Pure with respect to UI
/// state — the caller mutates `App` based on the returned outcome.
pub(crate) fn dispatch_quick_action(action: QuickAction, fx: &mut dyn Effects) -> ActionOutcome {
    match action {
        QuickAction::TerminateNode(key) => match fx.terminate_node(&key) {
            Ok(()) => ActionOutcome::Ok(format!("✔ closed {}", topology_key_label(&key))),
            Err(error) => ActionOutcome::Err(format!("✗ close failed: {error}")),
        },
        QuickAction::InterruptPane(key) => match fx.interrupt_pane(&key) {
            Ok(()) => ActionOutcome::Ok(format!(
                "✔ interrupted {}",
                topology_key_label(&TopologyNodeKey::Pane(key))
            )),
            Err(error) => ActionOutcome::Err(format!("✗ interrupt failed: {error}")),
        },
        QuickAction::KillPane(pane_id) => match fx.kill_pane(&pane_id) {
            Ok(()) => ActionOutcome::Ok(format!("✔ killed pane {pane_id}")),
            Err(e) => ActionOutcome::Err(format!("✗ kill-pane failed: {e}")),
        },
        QuickAction::AbortTurn(pane_id) => match fx.send_ctrl_c(&pane_id) {
            Ok(()) => ActionOutcome::Ok(format!("✔ sent Ctrl-C to {pane_id}")),
            Err(e) => ActionOutcome::Err(format!("✗ abort failed: {e}")),
        },
        QuickAction::CopyPrompt(text) => match fx.copy_to_clipboard(&text) {
            Ok(via) if via.starts_with("tmpfile:") => {
                let path = via.trim_start_matches("tmpfile:");
                ActionOutcome::Ok(format!(
                    "✔ wrote prompt to {path} (no clipboard tool found)"
                ))
            }
            Ok(via) => ActionOutcome::Ok(format!("✔ copied prompt via {via}")),
            Err(e) => ActionOutcome::Err(format!("✗ copy failed: {e}")),
        },
        QuickAction::SpawnWork {
            dir,
            agent_label,
            launch,
            work,
        } => match fx.spawn_work(&dir, &launch, work.as_deref()) {
            Ok(name) => ActionOutcome::Ok(format!(
                "started {agent_label} in session/window {name} — Enter on its row to attach"
            )),
            Err(e) => ActionOutcome::Err(format!("spawn failed: {e}")),
        },
        QuickAction::SpawnAt {
            target,
            dir,
            name,
            agent_label,
            launch,
        } => match fx.spawn_at(&target, &dir, &name, agent_label, &launch) {
            Ok(result) => ActionOutcome::Ok(format!("started {agent_label} in {result}")),
            Err(error) => ActionOutcome::Err(format!("spawn failed: {error}")),
        },
        QuickAction::SendPrompt { pane_id, text } => match fx.send_prompt(&pane_id, &text) {
            Ok(()) => ActionOutcome::Ok(format!("✔ sent prompt to {pane_id}")),
            Err(e) => ActionOutcome::Err(format!("✗ send failed: {e}")),
        },
        QuickAction::SendPromptTo { pane, text } => match fx.send_prompt_to(&pane, &text) {
            Ok(()) => ActionOutcome::Ok(format!(
                "✔ sent prompt to {}",
                topology_key_label(&TopologyNodeKey::Pane(pane))
            )),
            Err(error) => ActionOutcome::Err(format!("✗ send failed: {error}")),
        },
        QuickAction::ShowHelp => ActionOutcome::HelpToggled,
    }
}

/// Push an [`ActionOutcome`] back into `App` state — sets the footer
/// hint with the appropriate severity level, or toggles `help_open`
/// for `HelpToggled`. Centralised so the run loop and tests can both
/// drive it.
pub(crate) fn apply_outcome_to_app(app: &mut App, outcome: ActionOutcome) {
    match outcome {
        ActionOutcome::Ok(msg) => app.set_hint(msg, HintLevel::Ok),
        ActionOutcome::Err(msg) => app.set_hint(msg, HintLevel::Err),
        ActionOutcome::HelpToggled => {
            app.help_open = !app.help_open;
        }
    }
}

/// The lines of text rendered into the `?` help overlay. Returned as
/// a Vec so the snapshot test can assert on the exact contents
/// without going through ratatui. Keep this in sync with the actual
/// keybinding matrix in `handle_event` — the overlay is the user's
/// canonical reference.
pub(crate) fn help_overlay_text() -> Vec<&'static str> {
    vec![
        "Filter & navigation",
        "  type or /       filter; / allows reserved first characters",
        "  Backspace/C-W   edit filter / delete previous word",
        "  Ctrl-U / Esc    clear filter; Esc again backs out / quits",
        "  ↑/↓ · j/k       move siblings in focus mode; visible nodes otherwise",
        "  ←/→ · h/l       parent/child in focus mode; collapse/expand otherwise",
        "  gg/G · Home/End first / last selectable row",
        "  PgUp/PgDn       page; Ctrl-U/Ctrl-D half page",
        "  Enter          attach via active window/pane or exact pane",
        "  n / w / R      new window/pane / work up / rename the row",
        "  a / A          ask / history; d deletes one · D clears all in A",
        "",
        "Commands & inspection",
        "  :              command palette (Tab completes)",
        "  o / Alt-P      open preview overlay",
        "  Alt-I / Alt-E  inspector / persistent event inbox",
        "  |              cycle list/inspector split (50/50 → 70/30 → 30/70)",
        "  Alt-A          attention-only filter",
        "  [/] · f/c      (in preview) agent / geometry / content",
        "  Enter          (in preview) jump to pinned pane",
        "  m / M          message selected agent / mailbox (b alias)",
        "  Alt-1/2 · W    screen topology / collab · W is the work table",
        "  v              (in collab) toggle table / sequence history",
        "  i / e          (in mailbox) claim inbox / reply",
        "Sorting",
        "  Alt-S/L/D/T    sibling name / latest / duration / state",
        "State markers",
        match crate::icon_set() {
            IconSet::Unicode => {
                "  ● working  ▶ input  ◆ choice  ■ error  ○ idle  ◌ starting  × stopped"
            }
            IconSet::Ascii => {
                "  * working  > input  ? choice  ! error  o idle  ~ starting  x stopped"
            }
        },
        "  TREE: ◇ subagent  ▸ shell  + process; helper-only trees hidden",
        "",
        "Quick actions (act on selected node)",
        "  Alt-C          copy last prompt to clipboard",
        "  Alt-K          close session/window/pane (confirm popup)",
        "  Alt-X          interrupt selected agent pane (confirm popup)",
        "  r/Ctrl-R/Alt-R force refresh while browsing",
    ]
}

/// Modal confirmation popup state — mirrors the preview-popup pattern
/// (centred ratatui rect over the table) but with a binary y/N choice
/// instead of scrollable content.
///
/// **Why default focus is "No"**: the actions this gates (`K` kills the
/// pane, `R` aborts the agent's turn, `D` clears ask history) are destructive
/// enough that we want the user to deliberately type `y` rather than
/// fat-finger Enter.
/// Anything other than `y` / `Y` cancels — including Esc, `n`, `q`,
/// arrow keys, Tab.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct ConfirmPopup {
    /// One-line message, e.g. `Kill pane main:2.0?`. Caller pre-formats
    /// the pane label so the popup itself stays presentation-only.
    pub message: String,
    /// What to dispatch when the user confirms with `y` / `Y`. Held
    /// here so the input handler can complete the round-trip without
    /// re-resolving the selected row (which might have moved between
    /// the popup opening and the user's reply).
    pub on_confirm: ConfirmAction,
}

/// Inline prompt composer opened from the table with Enter. It pins the
/// target pane at open time so background refreshes or resorting cannot
/// redirect a typed prompt to a different row.
/// `a` — a headless question to the configured agent. One text field;
/// the contract lives in config, not in the composer.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct AskComposer {
    input: String,
    cursor: usize,
    /// Ask shares the reusable text palette with message composition, but
    /// selection never changes the daemon-owned agent/permission contract.
    skill_palette: Option<MessageSkillPalette>,
}

/// The `w` composer: a work id, nothing else.
///
/// Deliberately not folded into [`AskComposer`]. Ask is a read-only question
/// to a headless agent; this one spends money and creates panes, and the two
/// wanting the same text box is not a reason to give them the same key.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct WorkComposer {
    input: String,
    cursor: usize,
}

/// Which level of the tree `R` is renaming, and what tmux calls the thing.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RenameLevel {
    Session,
    Window,
    Pane,
}

impl RenameLevel {
    fn label(self) -> &'static str {
        match self {
            RenameLevel::Session => "session",
            RenameLevel::Window => "window",
            // tmux has no pane *name*; the closest durable, displayable
            // string is the pane title, which is what watch already shows.
            RenameLevel::Pane => "pane title",
        }
    }
}

/// Rename form for the row under the cursor. Carries the node key rather than
/// re-reading the selection on submit: a refresh can move the cursor while the
/// form is open, and renaming whatever happens to be selected a second later
/// is not what the user asked for.
#[derive(Debug, Clone, PartialEq, Eq)]
struct RenameComposer {
    key: TopologyNodeKey,
    level: RenameLevel,
    original: String,
    input: String,
    cursor: usize,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
enum MessageSkillEditorField {
    #[default]
    Name,
    Prompt,
}

/// In-watch registration form opened from either `/` palette. Persistence is
/// dispatched by the run loop so input handling stays side-effect free.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct MessageSkillEditor {
    name: String,
    name_cursor: usize,
    prompt: String,
    prompt_cursor: usize,
    field: MessageSkillEditorField,
}

impl MessageSkillEditor {
    fn field_mut(&mut self) -> (&mut String, &mut usize) {
        match self.field {
            MessageSkillEditorField::Name => (&mut self.name, &mut self.name_cursor),
            MessageSkillEditorField::Prompt => (&mut self.prompt, &mut self.prompt_cursor),
        }
    }

    fn cycle_field(&mut self) {
        self.field = match self.field {
            MessageSkillEditorField::Name => MessageSkillEditorField::Prompt,
            MessageSkillEditorField::Prompt => MessageSkillEditorField::Name,
        };
    }
}

/// History filter. Reading past answers and choosing the next agent are
/// different jobs, so the panel filters rather than switching: `All` is
/// the common case, and the per-agent views answer "what did codex say
/// about this" without disturbing who the next question goes to.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
enum AskFilter {
    #[default]
    All,
    Claude,
    Codex,
}

impl AskFilter {
    fn next(self) -> Self {
        match self {
            Self::All => Self::Claude,
            Self::Claude => Self::Codex,
            Self::Codex => Self::All,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::All => "all",
            Self::Claude => "claude",
            Self::Codex => "codex",
        }
    }

    fn matches(self, agent: &str) -> bool {
        match self {
            Self::All => true,
            Self::Claude => agent == "claude",
            Self::Codex => agent == "codex",
        }
    }
}

/// `A` — the ask history panel. Same shape as the collaboration mailbox
/// because it answers the same question ("what did I send, what came
/// back"), down to `|` cycling the detail height.
#[derive(Debug, Clone, Default)]
struct AskPanelState {
    open: bool,
    /// Index into the *filtered* list, not the raw history — the cursor
    /// should stay on a row the user can see.
    selected: usize,
    detail: MailboxDetail,
    filter: AskFilter,
}

/// Which agent CLI the spawn form launches. `Left`/`Right` cycle it.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
enum SpawnAgent {
    #[default]
    Claude,
    Codex,
    Gemini,
    Antigravity,
    Opencode,
}

impl SpawnAgent {
    fn label(self) -> &'static str {
        match self {
            Self::Claude => "claude",
            Self::Codex => "codex",
            Self::Gemini => "gemini",
            Self::Antigravity => "agy",
            Self::Opencode => "opencode",
        }
    }

    fn next(self) -> Self {
        match self {
            Self::Claude => Self::Codex,
            Self::Codex => Self::Gemini,
            Self::Gemini => Self::Antigravity,
            Self::Antigravity => Self::Opencode,
            Self::Opencode => Self::Claude,
        }
    }

    fn prev(self) -> Self {
        match self {
            Self::Claude => Self::Opencode,
            Self::Codex => Self::Claude,
            Self::Gemini => Self::Codex,
            Self::Antigravity => Self::Gemini,
            Self::Opencode => Self::Antigravity,
        }
    }

    /// The interactive launch line, first prompt included, so the agent
    /// boots already working — no fragile "wait for the REPL, then type"
    /// timing. Mirrors callabo-resolve's launcher matrix, bypass flags
    /// included: a spawned session is fire-and-forget by construction, and
    /// an agent parked on its first permission prompt in a window nobody
    /// is watching never runs the command it was created for.
    fn launch_command(self, prompt: &str) -> String {
        let quoted = shell_single_quote(prompt);
        match self {
            Self::Claude => format!("claude --dangerously-skip-permissions {quoted}"),
            Self::Codex => {
                format!("codex --dangerously-bypass-approvals-and-sandbox {quoted}")
            }
            Self::Gemini => format!("gemini --approval-mode yolo --skip-trust -i {quoted}"),
            Self::Antigravity => format!("agy --dangerously-skip-permissions -i {quoted}"),
            Self::Opencode => format!("opencode --prompt {quoted}"),
        }
    }
}

/// Cursor-aware multi-char insertion shared by paste paths.
fn insert_str_at(text: &mut String, cursor: &mut usize, pasted: &str) {
    let idx = char_to_byte_idx(text, *cursor);
    text.insert_str(idx, pasted);
    *cursor += pasted.chars().count();
}

/// Best-effort system clipboard read for terminals where `Ctrl-V` reaches
/// us as a plain keypress instead of a bracketed paste. Mirrors
/// `copy_to_clipboard`'s backend cascade in reverse; first non-empty
/// answer wins.
fn system_clipboard_text() -> Option<String> {
    let in_tmux = std::env::var_os("TMUX").is_some();
    let in_wayland = std::env::var_os("WAYLAND_DISPLAY").is_some();
    let in_x11 = std::env::var_os("DISPLAY").is_some();
    let candidates: [(&str, &[&str], bool); 5] = [
        ("tmux", &["save-buffer", "-"], in_tmux),
        ("pbpaste", &[], cfg!(target_os = "macos")),
        ("wl-paste", &["--no-newline"], in_wayland),
        ("xclip", &["-selection", "clipboard", "-o"], in_x11),
        ("xsel", &["-b", "-o"], in_x11),
    ];
    for (bin, args, applicable) in candidates {
        if !applicable {
            continue;
        }
        let Ok(out) = std::process::Command::new(bin).args(args).output() else {
            continue;
        };
        if !out.status.success() {
            continue;
        }
        let text = String::from_utf8_lossy(&out.stdout).into_owned();
        if !text.is_empty() {
            return Some(text);
        }
    }
    None
}

/// Wrap `text` into display rows of at most `avail` terminal cells,
/// width-aware so wide glyphs (Korean, CJK) never overflow a row the way
/// char-counted chunking would. Returns each row with the char index it
/// starts at, which is what maps a cursor to (row, column).
fn wrap_input_rows(text: &str, avail: usize) -> Vec<(String, usize)> {
    use unicode_width::UnicodeWidthChar;
    let avail = avail.max(4);
    let mut rows = Vec::new();
    let mut row = String::new();
    let mut row_start = 0usize;
    let mut row_width = 0usize;
    for (i, c) in text.chars().enumerate() {
        let w = c.width().unwrap_or(0);
        if row_width + w > avail && !row.is_empty() {
            rows.push((std::mem::take(&mut row), row_start));
            row_start = i;
            row_width = 0;
        }
        row.push(c);
        row_width += w;
    }
    rows.push((row, row_start));
    rows
}

/// POSIX-safe single quoting: close, escape the quote, reopen.
fn shell_single_quote(text: &str) -> String {
    format!("'{}'", text.replace('\'', "'\\''"))
}

/// tmux session names cannot contain `.` or `:`; everything else from a
/// directory basename passes through.
fn session_base_name(dir: &str) -> String {
    let base = std::path::Path::new(dir)
        .file_name()
        .and_then(|s| s.to_str())
        .unwrap_or("agent");
    let cleaned: String = base
        .chars()
        .map(|c| if c == '.' || c == ':' { '-' } else { c })
        .collect();
    if cleaned.is_empty() {
        "agent".into()
    } else {
        cleaned
    }
}

/// Fields of the spawn form, in Tab order.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
enum SpawnField {
    Dir,
    Name,
    Agent,
    #[default]
    Prompt,
}

/// `n` creates a window with its first agent or adds a sibling agent pane,
/// depending on the selected topology level.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct SpawnComposer {
    /// Stable node selected when the form opened. Background refresh cannot
    /// redirect the eventual spawn to another session/window.
    target: Option<TopologyNodeKey>,
    dir: String,
    dir_cursor: usize,
    /// Work id. Empty means derive it from the directory.
    name: String,
    name_cursor: usize,
    agent: SpawnAgent,
    prompt: String,
    prompt_cursor: usize,
    focus: SpawnField,
}

impl SpawnComposer {
    fn creates_window(&self) -> bool {
        matches!(self.target, None | Some(TopologyNodeKey::Session(_)))
    }

    fn field_mut(&mut self) -> Option<(&mut String, &mut usize)> {
        match self.focus {
            SpawnField::Dir => Some((&mut self.dir, &mut self.dir_cursor)),
            SpawnField::Name if self.creates_window() => {
                Some((&mut self.name, &mut self.name_cursor))
            }
            SpawnField::Prompt => Some((&mut self.prompt, &mut self.prompt_cursor)),
            SpawnField::Name | SpawnField::Agent => None,
        }
    }

    fn next_focus(&self) -> SpawnField {
        match self.focus {
            SpawnField::Dir if self.creates_window() => SpawnField::Name,
            SpawnField::Dir | SpawnField::Name => SpawnField::Agent,
            SpawnField::Agent => SpawnField::Prompt,
            SpawnField::Prompt => SpawnField::Dir,
        }
    }

    fn previous_focus(&self) -> SpawnField {
        match self.focus {
            SpawnField::Dir => SpawnField::Prompt,
            SpawnField::Agent if self.creates_window() => SpawnField::Name,
            SpawnField::Name | SpawnField::Agent => SpawnField::Dir,
            SpawnField::Prompt => SpawnField::Agent,
        }
    }
}

/// The three table/inspector splits `|` cycles through. Presets rather
/// than free resize: two keystrokes reach any of them, and a TUI resize
/// mode would cost a modal state for a knob that has three useful values.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
enum InspectorSplit {
    #[default]
    Balanced,
    ListWide,
    InspectorWide,
}

impl InspectorSplit {
    fn list_pct(self) -> u16 {
        match self {
            Self::Balanced => 50,
            Self::ListWide => 70,
            Self::InspectorWide => 30,
        }
    }

    fn next(self) -> Self {
        match self {
            Self::Balanced => Self::ListWide,
            Self::ListWide => Self::InspectorWide,
            Self::InspectorWide => Self::Balanced,
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Balanced => "50/50",
            Self::ListWide => "70/30",
            Self::InspectorWide => "30/70",
        }
    }

    fn from_label(label: &str) -> Option<Self> {
        match label {
            "50/50" => Some(Self::Balanced),
            "70/30" => Some(Self::ListWide),
            "30/70" => Some(Self::InspectorWide),
            _ => None,
        }
    }
}

/// Persist the cycled split next to the persisted sort, so the divider a
/// user drags into place survives the popup closing.
fn persist_watch_inspector_split(path: &Path, label: &str) -> std::result::Result<(), String> {
    let original = match std::fs::read_to_string(path) {
        Ok(s) => s,
        Err(e) if e.kind() == io::ErrorKind::NotFound => String::new(),
        Err(e) => return Err(format!("read {}: {e}", path.display())),
    };
    let mut doc = if original.trim().is_empty() {
        toml_edit::DocumentMut::new()
    } else {
        original
            .parse::<toml_edit::DocumentMut>()
            .map_err(|e| format!("parse {}: {e}", path.display()))?
    };
    match doc.get("watch") {
        Some(toml_edit::Item::Table(_)) | None => {}
        Some(_) => return Err("[watch] is not a table".to_string()),
    }
    if doc.get("watch").is_none() {
        doc["watch"] = toml_edit::Item::Table(toml_edit::Table::new());
    }
    let watch = doc["watch"]
        .as_table_mut()
        .ok_or_else(|| "[watch] is not a table".to_string())?;
    watch["inspector_split"] = toml_edit::value(label);
    if let Some(parent) = path.parent().filter(|p| !p.as_os_str().is_empty()) {
        std::fs::create_dir_all(parent).map_err(|e| format!("create {}: {e}", parent.display()))?;
    }
    std::fs::write(path, doc.to_string()).map_err(|e| format!("write {}: {e}", path.display()))
}

/// Persist the last request badges as watch preferences. They belong in the
/// existing `[watch]` table because they are composer UI state, not daemon
/// collaboration policy.
fn persist_watch_collaboration_defaults(
    path: &Path,
    defaults: CollaborationComposeDefaults,
) -> std::result::Result<(), String> {
    let original = match std::fs::read_to_string(path) {
        Ok(s) => s,
        Err(e) if e.kind() == io::ErrorKind::NotFound => String::new(),
        Err(e) => return Err(format!("read {}: {e}", path.display())),
    };
    let mut doc = if original.trim().is_empty() {
        toml_edit::DocumentMut::new()
    } else {
        original
            .parse::<toml_edit::DocumentMut>()
            .map_err(|e| format!("parse {}: {e}", path.display()))?
    };
    match doc.get("watch") {
        Some(toml_edit::Item::Table(_)) | None => {}
        Some(_) => return Err("[watch] is not a table".to_string()),
    }
    if doc.get("watch").is_none() {
        doc["watch"] = toml_edit::Item::Table(toml_edit::Table::new());
    }
    let watch = doc["watch"]
        .as_table_mut()
        .ok_or_else(|| "[watch] is not a table".to_string())?;
    let kind = match defaults.kind {
        RequestKind::Question => "question",
        RequestKind::Review => "review",
        RequestKind::Task => "task",
        RequestKind::Notice => "notice",
    };
    let mode = match defaults.mode {
        ComposeSendMode::ReadOnly => "read_only",
        ComposeSendMode::Execute => "execute",
        ComposeSendMode::JustSend => "just_send",
    };
    watch["collaboration_kind"] = toml_edit::value(kind);
    watch["collaboration_mode"] = toml_edit::value(mode);
    if let Some(parent) = path.parent().filter(|p| !p.as_os_str().is_empty()) {
        std::fs::create_dir_all(parent).map_err(|e| format!("create {}: {e}", parent.display()))?;
    }
    std::fs::write(path, doc.to_string()).map_err(|e| format!("write {}: {e}", path.display()))
}

