    #[test]
    fn spawn_composer_only_edits_a_window_name_for_session_targets() {
        let (agents, panes) = basic_topology_fixture();
        let mut app = topology_watch(WatchView::Window, agents, panes);

        app.table_state.select(Some(0));
        assert!(matches!(key_action(&mut app, 'n'), Action::None));
        let session_spawn = app.spawn.as_mut().expect("session spawn composer");
        assert!(matches!(
            session_spawn.target.as_ref(),
            Some(TopologyNodeKey::Session(_))
        ));
        assert!(session_spawn.name.is_empty());
        session_spawn.focus = SpawnField::Dir;
        let _ = handle_spawn_event(KeyCode::Tab, KeyModifiers::NONE, &mut app);
        assert_eq!(app.spawn.as_ref().unwrap().focus, SpawnField::Name);

        app.spawn = None;
        app.table_state.select(Some(1));
        let expected_window = app.topology.sessions[0].windows[0].name.clone();
        assert!(matches!(key_action(&mut app, 'n'), Action::None));
        let window_spawn = app.spawn.as_mut().expect("window spawn composer");
        assert!(matches!(
            window_spawn.target.as_ref(),
            Some(TopologyNodeKey::Window(_))
        ));
        assert_eq!(window_spawn.name, expected_window);
        window_spawn.focus = SpawnField::Dir;
        let _ = handle_spawn_event(KeyCode::Tab, KeyModifiers::NONE, &mut app);
        assert_eq!(app.spawn.as_ref().unwrap().focus, SpawnField::Agent);
    }

    fn fake_collaboration_participant(
        pane: &str,
        session_id: &str,
        alias: Option<&str>,
    ) -> Participant {
        Participant {
            agent_kind: AgentKind::Codex,
            agent_session_id: session_id.into(),
            pane: pane.into(),
            socket: Some("default".into()),
            room: RoomId {
                host: "tmux".into(),
                socket: Some("default".into()),
                window_id: "@1".into(),
            },
            tmux_session_id: Some("$1".into()),
            tmux_session_name: Some("main".into()),
            window_name: Some("agents".into()),
            state: AgentState::Idle,
            cwd: Some("/tmp/project".into()),
            alias: alias.map(str::to_string),
            roles: Vec::new(),
            console: false,
        }
    }

    fn fake_watch_collaboration_request(
        id: &str,
        from: Participant,
        to: Participant,
        status: RequestStatus,
    ) -> CollaborationRequest {
        let now = OffsetDateTime::now_utc();
        CollaborationRequest {
            id: id.into(),
            from,
            to,
            provenance: None,
            kind: RequestKind::Review,
            body: "review the auth change".into(),
            expects_reply: true,
            work_mode: WorkMode::ReadOnly,
            thread_id: None,
            parent_request_id: None,
            workspace_id: None,
            work_id: None,
            run_id: None,
            paths: Vec::new(),
            artifacts: Vec::new(),
            links: Vec::new(),
            air_artifacts: Vec::new(),
            status,
            created_at: now,
            claimed_at: (status == RequestStatus::Claimed).then_some(now),
            wake_delivery: None,
            notified_at: None,
            reply_notified_at: None,
            reply_read_at: None,
            reply: None,
        }
    }

    fn participant_on(
        pane: &str,
        socket: &str,
        session_id: &str,
        session: &str,
        window_id: &str,
        window: &str,
    ) -> Participant {
        let mut participant = fake_collaboration_participant(pane, pane, None);
        participant.socket = Some(socket.into());
        participant.room.socket = Some(socket.into());
        participant.room.window_id = window_id.into();
        participant.tmux_session_id = Some(session_id.into());
        participant.tmux_session_name = Some(session.into());
        participant.window_name = Some(window.into());
        participant
    }

    #[test]
    fn aggregate_session_history_is_exact_socket_scoped_and_de_duplicates_internal_traffic() {
        let scope = MailboxHistoryScope::Session {
            key: SessionKey {
                endpoint: BackendEndpoint {
                    host: muxa::HostKind::Tmux,
                    socket: "default".into(),
                },
                session_id: "$1".into(),
            },
            label: "callabo".into(),
        };
        let internal = fake_watch_collaboration_request(
            "internal",
            participant_on("%1", "default", "$1", "callabo", "@1", "CAL-1"),
            participant_on("%2", "default", "$1", "callabo", "@2", "CAL-2"),
            RequestStatus::Completed,
        );
        let cross_socket = fake_watch_collaboration_request(
            "other-socket",
            participant_on("%1", "amux", "$1", "other", "@1", "CAL-1"),
            participant_on("%2", "amux", "$1", "other", "@2", "CAL-2"),
            RequestStatus::Completed,
        );
        let mut missing_socket = participant_on("%3", "default", "$1", "callabo", "@1", "CAL-1");
        missing_socket.socket = None;
        missing_socket.room.socket = None;
        let missing_socket = fake_watch_collaboration_request(
            "missing-socket",
            missing_socket,
            Participant::console(RoomId {
                host: "tmux".into(),
                socket: Some("default".into()),
                window_id: "@1".into(),
            }),
            RequestStatus::Completed,
        );

        let history = history_for_scope(&[internal, cross_socket, missing_socket], &scope);
        assert_eq!(
            history.len(),
            1,
            "one internal request, never one per endpoint"
        );
        assert_eq!(history[0].id, "internal");
    }

