        app.spawn.as_mut().unwrap().prompt = "go".into();
        app.spawn.as_mut().unwrap().dir = "/definitely/not/a/dir".into();
        let action = handle_spawn_event(KeyCode::Enter, KeyModifiers::NONE, &mut app);
